480	    /**
481	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
482	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
483	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
484	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
485	     * string is what gets stored and returned.
486	     *
487	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
488	     *
489	     * <p>Once in E.164 form the national-number length is validated against the country code: a
490	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
491	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
492	     * rule are accepted on the general 8-to-15 digit length alone.
493	     *
494	     * @param telephone the raw telephone value supplied by the client
495	     * @return the normalized E.164 telephone number
496	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
497	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
498	     *                                 after the {@code '+'}, or the wrong national-number length for
499	     *                                 its country code)
500	     */
501	    private static String normalizeTelephone(String telephone) {
502	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
503	        String digits;
504	        if (cleaned.startsWith("+")) {
505	            digits = cleaned.substring(1);
506	        } else {
507	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
508	            digits = "61" + national;
509	        }
510	        if (!digits.matches("[0-9]{8,15}")) {
511	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
512	                "telephone could not be normalized to a valid E.164 number");
513	        }
514	        validateNationalNumberLength(digits);
515	        return "+" + digits;
516	    }
517	
518	    /**
519	     * Validates the national-number length of an E.164 number (its digits, without the leading
520	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
521	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
522	     * (only the general 8-to-15 digit rule applies).
523	     *
524	     * @param digits the E.164 digits without the leading {@code '+'}
525	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
526	     *                                 digits does not match the country code's required length
527	     */
528	    private static void validateNationalNumberLength(String digits) {
529	        E164PhoneNumbers.countryCode(digits)
530	            .ifPresent(code -> {
531	                int nationalLength = digits.length() - code.length();
532	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
533	                if (nationalLength != required) {
534	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
535	                        "telephone must have " + required
536	                            + " national digits for country code +" + code);
537	                }
538	            });
539	    }
