541	    /**
542	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
543	     * containing at least one dot, none of the three sections containing whitespace or an
544	     * additional {@code @}.
545	     */
546	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
547	
548	    /**
549	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
550	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
551	     * case-insensitively against the domain (the part after the {@code @}).
552	     */
553	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
554	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
555	
556	    /**
557	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
558	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
559	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
560	     * lower-cased.
561	     *
562	     * @param email the raw email value supplied by the client, possibly {@code null}
563	     * @return the lower-cased email, or {@code null} when none was supplied
564	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
565	     *                                 is not a syntactically valid address, or its domain is on the
566	     *                                 disposable-domain blocklist
567	     */
568	    private static String normalizeEmail(String email) {
569	        if (email == null) {
570	            return null;
571	        }
572	        if (!EMAIL_PATTERN.matcher(email).matches()) {
573	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
574	                "email must be a syntactically valid address");
575	        }
576	        String normalized = email.toLowerCase(Locale.ROOT);
577	        String domain = normalized.substring(normalized.indexOf('@') + 1);
578	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
579	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
580	                "email domain " + domain + " is not allowed");
581	        }
582	        return normalized;
583	    }
