585	    /**
586	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
587	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
588	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
589	     */
590	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
591	        "NSW", new int[] {2000, 2099},
592	        "VIC", new int[] {3000, 3099},
593	        "QLD", new int[] {4000, 4099});
594	
595	    /**
596	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
597	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
598	     * four-digit format is enforced by request validation; here the value is range-checked: when the
599	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
600	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
601	     * accepts any four-digit postcode.
602	     *
603	     * @param city     the owner's city
604	     * @param postcode the owner's postcode, possibly {@code null}
605	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
606	     *                                 out of range for the city's region
607	     */
608	    private static void validatePostcode(String city, String postcode) {
609	        if (postcode == null) {
610	            return;
611	        }
612	        String region = OwnerMapper.CITY_REGION.get(city);
613	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
614	        if (range == null) {
615	            return;
616	        }
617	        int value = Integer.parseInt(postcode);
618	        if (value < range[0] || value > range[1]) {
619	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
620	                "postcode " + postcode + " is not valid for region " + region);
621	        }
622	    }
623	
624	    /**
625	     * Common street-type abbreviations expanded to their full word during address normalization.
626	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
627	     */
628	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
629	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
630	
631	    /**
632	     * Applies an owner's address, accepting either the structured form (a non-blank
633	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
634	     * preferring the structured fields when present. Whichever fields are supplied are normalized
635	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
636	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
637	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
638	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
639	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
640	     * {@code address} (plus city) is still accepted.
641	     *
642	     * @param owner the owner being created or updated, carrying the raw address fields
643	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
644	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
645	     *                                 supplied
646	     */
647	    private static void applyAddress(Owner owner) {
648	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
649	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
650	        if (!hasStructured && !hasFlat) {
651	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
652	                "an address must be supplied, either 'addressLine1' or 'address'");
653	        }
654	        if (hasStructured) {
655	            String line1 = normalizeAddress(owner.getAddressLine1());
656	            owner.setAddressLine1(line1);
657	            String composed = line1;
658	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
659	                String line2 = normalizeAddress(owner.getAddressLine2());
660	                owner.setAddressLine2(line2);
661	                composed = line1 + " " + line2;
662	            } else {
663	                owner.setAddressLine2(null);
664	            }
665	            owner.setAddress(composed);
666	        } else {
667	            owner.setAddressLine1(null);
668	            owner.setAddressLine2(null);
669	            owner.setAddress(normalizeAddress(owner.getAddress()));
670	        }
671	    }
672	
673	    /**
674	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
675	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
676	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
677	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
678	     *
679	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
680	     *
681	     * @param address the raw address supplied by the client, possibly {@code null}
682	     * @return the normalized address
683	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
684	     *                                 after normalization (required field)
685	     */
686	    private static String normalizeAddress(String address) {
687	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
688	        if (collapsed.isEmpty()) {
689	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
690	                "address must not be blank");
691	        }
692	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
693	        StringBuilder normalized = new StringBuilder();
694	        for (int i = 0; i < tokens.length; i++) {
695	            if (i > 0) {
696	                normalized.append(' ');
697	            }
698	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
699	        }
700	        return normalized.toString();
701	    }
702	
703	    /**
704	     * Determines whether the given whole identity key already belongs to any owner other than the
705	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
706	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
707	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
708	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
709	     *
710	     * @param identityKey the identity key to look for
711	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
712	     * @return {@code true} if another owner already has the same identity key
713	     */
714	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
715	        for (Owner existing : this.clinicService.findAllOwners()) {
716	            if (existing.isDeleted()) {
717	                continue;
718	            }
719	            if (excludeId != null && excludeId.equals(existing.getId())) {
720	                continue;
721	            }
722	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
723	                return true;
724	            }
725	        }
726	        return false;
727	    }
728	
729	    /**
730	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
731	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
732	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
733	     * (identical identity key) has already been rejected with a 409 before this runs, so this
734	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
735	     * so the result is deterministic when several owners qualify.
736	     *
737	     * @param owner the new owner being created, with its telephone already normalized
738	     * @return the matching existing owner, or {@code null} when none qualifies
739	     */
740	    private Owner findPossibleDuplicate(Owner owner) {
741	        if (owner.getLastName() == null || owner.getPostcode() == null) {
742	            return null;
743	        }
744	        return this.clinicService.findAllOwners().stream()
745	            .filter(existing -> !existing.isDeleted())
746	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
747	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
748	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
749	            .min(Comparator.comparingInt(Owner::getId))
750	            .orElse(null);
751	    }
752	
753	}
