     * {@code fiscalYear} and the create endpoint's membership-number year segment.
     *
     * @param date the date to resolve, on a business day
     * @return the calendar year in which that date's fiscal year ends
     */
    static int fiscalYear(LocalDate date) {
        int year = date.getYear();
        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? year + 1 : year;
    }

    /**
     * The fiscal-year label for the given date, formatted {@code 'FY<YY>'} where YY is the last two
     * digits of the fiscal year (see {@link #fiscalYear(LocalDate)}), e.g. {@code 'FY27'}.
     *
     * @param date the date to resolve, on a business day
     * @return the {@code 'FY<YY>'} label for that date's fiscal year
     */
    static String fiscalYearLabel(LocalDate date) {
        return String.format("FY%02d", fiscalYear(date) % 100);
    }

    /**
     * Derive an owner's fiscal year from its business-day-adjusted {@code registrationDate},
     * formatted {@code 'FY<YY>'} (see {@link #fiscalYearLabel(LocalDate)}). Returns {@code null} when
     * no registration date is present (the field is then absent from the DTO).
     */
    default String toFiscalYear(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        return registrationDate == null ? null : fiscalYearLabel(registrationDate);
    }

    /**
     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
     * just the last name.
     */
    default String toSalutation(Owner owner) {
        String lastName = owner.getLastName();
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
            return lastName;
        }
        return title + " " + lastName;
    }

